import{_ as t,c as n,o,ah as p}from"./chunks/framework.PvdZnrZd.js";const d=JSON.parse('{"title":"Multiple Shipping","description":"Multiple Shipping","frontmatter":{"title":"Multiple Shipping","description":"Multiple Shipping","author":"Chirag Tyagi"},"headers":[],"relativePath":"zenith/marketplace-shipping/multiple-shipping.md","filePath":"zenith/marketplace-shipping/multiple-shipping.md"}'),l={name:"zenith/marketplace-shipping/multiple-shipping.md"};function r(a,e,i,s,g,h){return o(),n("div",null,[...e[0]||(e[0]=[p('<p>If you are using <a href="/zenith/marketplace-shipping/marketplace-shipping.html">Multivendor Marketplace Shipping App</a> then now you will be able to <strong>create multiple shipping</strong> for your sellers.</p><p>In this documentation, we will only discuss how the admin can create multiple shipping and further, how the sellers can configure them.</p><p>To learn more about the marketplace shipping app, refer to this <a href="/zenith/marketplace-shipping/marketplace-shipping.html">blog</a>.</p><p><strong>Note</strong>: You will only be able to create multiple shipping if you are using <strong>Zone-Wise</strong> or <strong>Country-wise</strong> shipping type.</p><p>It will not work in the case of the Postcode-wise shipping type.</p><p>In case you want to change the shipping type from zone-wise/country-wise to postcode-wise then you first need to disable multiple shipping. Otherwise, you may face issues.</p><p>Also, if you are using this feature, you won&#39;t be able to fetch shipping rates using any other <a href="https://sp-seller.webkul.com/mvm-landing/addons/" target="_blank" rel="noreferrer">shipping module</a> of the marketplace app.</p><p>However, you can use these shipping modules for the fulfillment process.</p><p>These are all the points that you need to remember. Now, let&#39;s jump into the configuration part!</p><h2 id="enable-multiple-shipping" tabindex="-1">Enable Multiple Shipping <a class="header-anchor" href="#enable-multiple-shipping" aria-label="Permalink to &quot;Enable Multiple Shipping&quot;">​</a></h2><p>The admin needs to visit <strong>Multivendor Admin panel</strong> &gt; <strong>Configuration</strong> &gt; <strong>Marketplace Shipping Configuration</strong>. Here, you need to click on the following option:</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/02/Home-_-Admin-1200x590.png" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/02/Home-_-Admin-1200x590.png" alt="Home-_-Admin"></a></p><ul><li>Enable the &#39;<strong>Create Multiple Shipping</strong>&#39; option.</li><li>Choose where you want the shipping methods to display: <strong>Checkout Page</strong> or <strong>Product Page</strong>.</li></ul><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/11/image-15-1200x597.png" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/11/image-15-1200x597.png" alt="image-15"></a></p><p>On the same page, it is mandatory to enable the <a href="https://webkul.com/blog/shopify-multivendor-marketplace-shipping-calculator/" target="_blank" rel="noreferrer">shipping calculator</a> option:</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/03/image-5-1200x597.png" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/03/image-5-1200x597.png" alt="image-5"></a></p><p>On the bottom on this page, you will have the code that you need to paste for shipping calculator. <strong>Note</strong>: In the case of multiple shipping, this code needs to be pasted in the <strong>product.liquid</strong> file.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/03/image-6-1200x597.png" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/03/image-6-1200x597.png" alt="image-6"></a></p><h2 id="single-to-multiple-shipping-transfer" tabindex="-1">Single To Multiple Shipping Transfer <a class="header-anchor" href="#single-to-multiple-shipping-transfer" aria-label="Permalink to &quot;Single To Multiple Shipping Transfer&quot;">​</a></h2><p>If you&#39;ll switch from single to multiple shipping, you&#39;ll get an option to migrate current shipping data to the new multiple shipping data.</p><p>You can migrate the existing ranges by entering shipping method name.</p><p>Further, the existing products with marketplace shipping will be replaced by this new shipping method.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/02/download-1200x546.png" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/02/download-1200x546.png" alt="download"></a></p><h2 id="add-shipping-method" tabindex="-1">Add Shipping Method <a class="header-anchor" href="#add-shipping-method" aria-label="Permalink to &quot;Add Shipping Method&quot;">​</a></h2><p>Visit <strong>Multivendor Admin panel</strong> &gt; <strong>Configuration</strong> &gt; <strong>Shipping Methods</strong>. On this page, click on <strong>Add Shipping Method</strong>:</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/02/image-35-1200x597.png" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/02/image-35-1200x597.png" alt="image-35"></a></p><p>On the redirected page, add the Shipping Method:</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/10/Add-Shipping-Method-Admin-1200x597.png" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/10/Add-Shipping-Method-Admin-1200x597.png" alt="Add-Shipping-Method-Admin"></a></p><p>Next, enable these added methods:</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/10/Configuration-Admin-1-1-1200x559.png" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/10/Configuration-Admin-1-1-1200x559.png" alt="Configuration-Admin-1-1"></a></p><p>Once added &amp; enabled, the following methods will be listed on the seller end. Let&#39;s move on to the seller end configuration.</p><h2 id="seller-panel" tabindex="-1">Seller Panel <a class="header-anchor" href="#seller-panel" aria-label="Permalink to &quot;Seller Panel&quot;">​</a></h2><p>Visit <strong>Multivendor Seller Panel</strong> &gt; <strong>Configuration</strong> &gt; <strong>Marketplace Shipping</strong>: Enable the shipping status.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/11/image-21-1200x597.png" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/11/image-21-1200x597.png" alt="image-21"></a></p><p>The seller needs to visit <strong>Multivendor Seller Panel</strong> &gt; <strong>Configuration</strong> &gt; <strong>Shipping Configuration</strong>. Enable the shipping methods added by the admin:</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/10/Shipping-Configuration-Seller-%E2%80%A2-Multivendor-MarketPlace-1200x597.png" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/10/Shipping-Configuration-Seller-%E2%80%A2-Multivendor-MarketPlace-1200x597.png" alt="Shipping-Configuration-Seller-•-Multivendor-MarketPlace"></a></p><p>Further, the seller needs to add <strong>Range Details</strong>:</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/10/Shipping-Configuration-Seller-%E2%80%A2-Multivendor-MarketPlace-1-1200x597.png" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/10/Shipping-Configuration-Seller-%E2%80%A2-Multivendor-MarketPlace-1-1200x597.png" alt="Shipping-Configuration-Seller-•-Multivendor-MarketPlace-1"></a></p><p>After clicking on the Range Detail option, the seller will be redirected to the following page.</p><p>The seller then needs to click on the <strong>Add New Range</strong> button to set a shipping range to enter zone-wise shipping rates.</p><p>These rates will be applied on the basis of the product’s price or product’s weight.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/10/Range-Details-Seller-%E2%80%A2-Multivendor-MarketPlace-1200x597.png" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/10/Range-Details-Seller-%E2%80%A2-Multivendor-MarketPlace-1200x597.png" alt="Range-Details-Seller-•-Multivendor-MarketPlace"></a></p><p>Seller can set up to 8 ranges for a shipping method. Also, the seller can edit/delete the ranges.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/10/Range-Details-Seller-%E2%80%A2-Multivendor-MarketPlace-1-1200x750.png" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/10/Range-Details-Seller-%E2%80%A2-Multivendor-MarketPlace-1-1200x750.png" alt="Range-Details-Seller-•-Multivendor-MarketPlace-1"></a></p><p>Click on the <strong>View Shipping</strong> button as shown in the above image. Here, click on the marked location to add zone wise rates:</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/10/Shipping-Details-Seller-%E2%80%A2-Multivendor-MarketPlace-1200x597.png" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/10/Shipping-Details-Seller-%E2%80%A2-Multivendor-MarketPlace-1200x597.png" alt="Shipping-Details-Seller-•-Multivendor-MarketPlace"></a></p><p>Further, enter the shipping range prices:</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/10/Shipping-Details-Seller-%E2%80%A2-Multivendor-MarketPlace-1-1200x680.png" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/10/Shipping-Details-Seller-%E2%80%A2-Multivendor-MarketPlace-1-1200x680.png" alt="Shipping-Details-Seller-•-Multivendor-MarketPlace-1"></a></p><p>Once added, the rates can be deleted/edited/disabled.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/10/Shipping-Details-Seller-%E2%80%A2-Multivendor-MarketPlace-2-1200x713.png" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/10/Shipping-Details-Seller-%E2%80%A2-Multivendor-MarketPlace-2-1200x713.png" alt="Shipping-Details-Seller-•-Multivendor-MarketPlace-2"></a></p><p>This flow is as per zone-wise shipping. In case you want to know the flow to add country-wise shipping, refer: <a href="/zenith/marketplace-shipping/marketplace-shipping.html#country-wise-shipping-2">Country Wise Shipping</a></p><h2 id="add-shipping-to-products" tabindex="-1">Add Shipping to Products <a class="header-anchor" href="#add-shipping-to-products" aria-label="Permalink to &quot;Add Shipping to Products&quot;">​</a></h2><p>Visit <strong>Multivendor Seller Panel</strong> &gt; <strong>Products</strong> &gt; <strong>Product Listing</strong> &gt; <strong>Add/Edit Product</strong>. Add the shipping to the products (more than once shipping can be added to a product):</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/10/Edit-Product-Seller-%E2%80%A2-Multivendor-MarketPlace-1200x597.png" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/10/Edit-Product-Seller-%E2%80%A2-Multivendor-MarketPlace-1200x597.png" alt="Edit-Product-Seller-•-Multivendor-MarketPlace"></a></p><h3 id="shipping-on-product-page" tabindex="-1">Shipping on Product Page: <a class="header-anchor" href="#shipping-on-product-page" aria-label="Permalink to &quot;Shipping on Product Page:&quot;">​</a></h3><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/10/collage.png" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/10/collage.png" alt="collage"></a></p><h3 id="shipping-on-checkout-page" tabindex="-1">Shipping on Checkout Page: <a class="header-anchor" href="#shipping-on-checkout-page" aria-label="Permalink to &quot;Shipping on Checkout Page:&quot;">​</a></h3><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/10/Shipping-Sanjay-store-trunk-Checkout-1200x597.png" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/10/Shipping-Sanjay-store-trunk-Checkout-1200x597.png" alt="Shipping-Sanjay-store-trunk-Checkout"></a></p><h2 id="admin-managing-shipping-ranges" tabindex="-1">Admin Managing Shipping Ranges <a class="header-anchor" href="#admin-managing-shipping-ranges" aria-label="Permalink to &quot;Admin Managing Shipping Ranges&quot;">​</a></h2><p>In case you want to manage multiple shipping ranges &amp; set rates on your own then, this can be done.</p><p>For this, you need to visit the Multi-vendor admin panel <strong>Configuration</strong> &gt;&gt; <strong>Marketplace Shipping Configuration</strong>.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/08/screenshot-sp-seller.webkul.com-2021.08.13-10_46_57-1-1200x564.png" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/08/screenshot-sp-seller.webkul.com-2021.08.13-10_46_57-1-1200x564.png" alt="screenshot-sp-seller.webkul.com-2021.08.13-10_46_57-1"></a></p><p>Now, make sure to select shipping type as Create Multiple Shipping and then enable the tab &quot;<strong>Manage Shipping Range by Admin</strong>&quot; and <strong>Save</strong> the changes.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/08/Screenshot-2021-08-13T102959.949-1200x617.png" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/08/Screenshot-2021-08-13T102959.949-1200x617.png" alt="manage shipping"></a></p><p>Once you enable this tab, you will get the option to choose if you want to enable multiple shipping on the seller&#39;s products or not.</p><p>Enabling the <strong>&quot;Multiple Shipping on Seller Products&quot;</strong> configuration, all the active shipping methods of sellers will be selected on all (old and new) products of the sellers.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/08/screenshot-sp-seller.webkul.com-2021.08.13-11_36_46-1200x620.png" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/08/screenshot-sp-seller.webkul.com-2021.08.13-11_36_46-1200x620.png" alt="multiple shipping"></a></p><p>Now, you will have a new sub-menu &quot;<strong>Global Shipping Range&quot;</strong> added to the <strong>Configuration</strong> menu of the app.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/08/screenshot-sp-seller.webkul.com-2021.08.13-11_51_38-1200x620.png" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/08/screenshot-sp-seller.webkul.com-2021.08.13-11_51_38-1200x620.png" alt="global shipping range"></a></p><p>From here, you can add new shipping ranges.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/08/Screenshot-2021-08-13T115849.920-1200x510.png" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/08/Screenshot-2021-08-13T115849.920-1200x510.png" alt="new range"></a></p><p>Proceed to add shipping ranges based on the price &amp; weight of the product.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/08/Screenshot-2021-08-13T120009.680-1200x618.png" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/08/Screenshot-2021-08-13T120009.680-1200x618.png" alt="add range"></a></p><p>You can further edit the ranges and prices from the <strong>Shipping Configuration</strong> menu &gt;&gt; Select the shipping method and Edit Range/Price.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/08/screenshot-sp-seller.webkul.com-2021.08.13-16_03_01-1200x620.png" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/08/screenshot-sp-seller.webkul.com-2021.08.13-16_03_01-1200x620.png" alt="screenshot-sp-seller.webkul.com-2021.08.13-16_03_01"></a></p><h2 id="code-pasting" tabindex="-1">Code pasting <a class="header-anchor" href="#code-pasting" aria-label="Permalink to &quot;Code pasting&quot;">​</a></h2><p>In case you are using shipping on the product page, visit <strong>Multivendor Marketplace Admin Panel</strong> &gt; <strong>Configuration</strong> &gt; <strong>Instructions for Marketplace</strong>.</p><p>Add the following sets of code to the restrictive template files:</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/10/Instructions-Admin-1200x597.png" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/10/Instructions-Admin-1200x597.png" alt="Instructions-Admin"></a></p><p>In case you are using the <a href="/zenith/featured-app/marketplace-miscellaneous-add-ons/hyperlocal-marketplace.html"><strong>Hyperlocal Marketplace</strong></a> module, kindly check out: <a href="/zenith/featured-app/marketplace-miscellaneous-add-ons/hyperlocal-marketplace.html#hyperlocal-with-multiple-shipping"><strong>Hyperlocal with Multiple Shipping</strong></a></p><p><strong>Note</strong>: In case you need our help with code pasting, drop your request at <a href="mailto:shopify@webkul.com" target="_blank" rel="noreferrer">shopify@webkul.com</a>.</p><h3 id="case-scenario" tabindex="-1">Case Scenario <a class="header-anchor" href="#case-scenario" aria-label="Permalink to &quot;Case Scenario&quot;">​</a></h3><p><strong>CASE I</strong></p><p>Suppose, Seller has 2 products: <strong>Product A</strong> &amp; <strong>product B</strong></p><p>On product A, let say the seller has chosen: <strong>Method 1</strong> &amp; <strong>Method 2</strong><br> On product B, let say the seller has chosen: <strong>Method 2</strong> &amp; <strong>Method 3</strong></p><p>Then in this case, when customers add product A as well as product B then we&#39;ll get Method 2 common so then we&#39;ll display the shipping rates based on Method 2 on Shopify checkout.</p><p><strong>CASE II</strong></p><p>Suppose, Seller has 2 products: <strong>Product A</strong> &amp; <strong>product B</strong></p><p>On product A, let say the seller has chosen: <strong>Method 1</strong> &amp; <strong>Method 2</strong><br> On product B, let say the seller has chosen: <strong>Method</strong> <strong>3</strong> &amp; <strong>Method</strong> <strong>4</strong></p><p>Then in this case, when customer adds product A as well as product B then we won&#39;t be getting any common shipping method</p><p>so then we won&#39;t be able to display any shipping rates on the checkout page.</p>',91)])])}const u=t(l,[["render",r]]);export{d as __pageData,u as default};
